{
  "up": "Select molecule_dictionary.chembl_id AS chembl_id, molecule_dictionary.pref_name AS pref_name, compound_structures.canonical_smiles AS canonical_smiles, molecule_dictionary.max_phase AS max_phase, drug_indication.mesh_heading AS mesh_heading, molecule_dictionary.first_approval AS first_approval From molecule_dictionary Join drug_indication On molecule_dictionary.molregno = drug_indication.molregno Left Join compound_structures On molecule_dictionary.molregno = compound_structures.molregno Where molecule_dictionary.therapeutic_flag = 1 And molecule_dictionary.oral = 1 And molecule_dictionary.black_box_warning = 0 And molecule_dictionary.withdrawn_flag = 0 Order By molecule_dictionary.first_approval Desc"
}
